# 멀티스텝 워크플로우 스킬

실제 프로덕션 환경에서 AI 에이전트는 단일 작업만 수행하는 경우가 드뭅니다. 대부분의 복잡한 작업은 여러 단계를 거쳐 완료되며, 각 단계는 이전 단계의 결과에 의존합니다. 멀티스텝 워크플로우 스킬은 이러한 복잡한 작업을 체계적으로 관리하고 실행하는 패턴입니다.

## 순차 실행 패턴 (A→B→C)

순차 실행 패턴은 가장 기본적인 멀티스텝 워크플로우입니다. 각 단계가 순서대로 실행되며, 이전 단계의 출력이 다음 단계의 입력으로 사용됩니다.

```typescript
// 순차 실행 패턴 예시: 코드 분석 → 리팩토링 → 테스트
export const sequentialRefactoringSkill: Skill = {
  name: "sequential-refactoring",
  description: "코드를 분석하고, 리팩토링하고, 테스트하는 순차적 워크플로우",

  async execute(context: SkillContext) {
    const { prompt } = context;

    // Step 1: 코드 분석
    const analysisResult = await context.delegate({
      subagent_type: "oh-my-claudecode:architect",
      model: "sonnet",
      prompt: `다음 코드를 분석해주세요: ${prompt}`
    });

    // Step 2: 리팩토링 (분석 결과를 기반으로)
    const refactoringResult = await context.delegate({
      subagent_type: "oh-my-claudecode:executor",
      model: "sonnet",
      prompt: `다음 분석 결과를 바탕으로 코드를 리팩토링해주세요:\n${analysisResult.output}`
    });

    // Step 3: 테스트 실행
    const testResult = await context.delegate({
      subagent_type: "oh-my-claudecode:qa-tester",
      model: "sonnet",
      prompt: `리팩토링된 코드를 테스트해주세요:\n${refactoringResult.output}`
    });

    return {
      success: testResult.success,
      output: `분석 완료 → 리팩토링 완료 → 테스트 ${testResult.success ? '통과' : '실패'}`
    };
  }
};
```

이 패턴의 핵심은 데이터 흐름의 명확성입니다. 각 단계는 이전 단계의 결과를 받아 처리하고, 다음 단계로 전달합니다.

## 조건 분기 패턴

모든 워크플로우가 일직선으로 진행되는 것은 아닙니다. 상황에 따라 다른 경로를 선택해야 할 때가 있습니다.

```typescript
// 조건 분기 패턴 예시: 프로젝트 타입에 따라 다른 빌드 전략 선택
export const conditionalBuildSkill: Skill = {
  name: "conditional-build",
  description: "프로젝트 타입을 감지하고 적절한 빌드 전략을 선택",

  async execute(context: SkillContext) {
    // Step 1: 프로젝트 타입 감지
    const projectType = await context.delegate({
      subagent_type: "oh-my-claudecode:explore",
      model: "haiku",
      prompt: "프로젝트 타입을 확인해주세요 (React, Vue, Node.js, Python 등)"
    });

    // Step 2: 조건에 따른 분기
    let buildResult;

    if (projectType.output.includes("React") || projectType.output.includes("Vue")) {
      // 프론트엔드 프로젝트 빌드 전략
      buildResult = await context.delegate({
        subagent_type: "oh-my-claudecode:executor",
        model: "sonnet",
        prompt: "프론트엔드 프로젝트를 빌드하고 최적화해주세요. npm run build 실행 후 번들 크기를 분석해주세요."
      });
    } else if (projectType.output.includes("Python")) {
      // Python 프로젝트 빌드 전략
      buildResult = await context.delegate({
        subagent_type: "oh-my-claudecode:executor",
        model: "sonnet",
        prompt: "Python 프로젝트의 의존성을 확인하고 requirements.txt를 업데이트해주세요."
      });
    } else {
      // 기본 빌드 전략
      buildResult = await context.delegate({
        subagent_type: "oh-my-claudecode:executor",
        model: "sonnet",
        prompt: "일반적인 빌드 프로세스를 실행해주세요."
      });
    }

    return buildResult;
  }
};
```

조건 분기는 유연성을 제공합니다. 동일한 스킬이 다양한 상황에 대응할 수 있게 됩니다.

## 반복 패턴 (검증→수정 루프)

품질 기준을 충족할 때까지 반복적으로 작업을 수행하는 패턴입니다. 이는 TDD(테스트 주도 개발)나 품질 보증 워크플로우에서 특히 유용합니다.

```typescript
// 반복 패턴 예시: 품질 기준을 충족할 때까지 코드 개선
export const iterativeImprovementSkill: Skill = {
  name: "iterative-improvement",
  description: "품질 기준을 충족할 때까지 코드를 반복적으로 개선",

  async execute(context: SkillContext) {
    const maxIterations = 5;
    let currentIteration = 0;
    let qualityMet = false;
    let lastResult;

    while (!qualityMet && currentIteration < maxIterations) {
      currentIteration++;

      // 코드 개선 시도
      const improvementResult = await context.delegate({
        subagent_type: "oh-my-claudecode:executor",
        model: "sonnet",
        prompt: currentIteration === 1 
          ? `${context.prompt}을 구현해주세요.`
          : `이전 검증 결과를 바탕으로 코드를 개선해주세요:\n${lastResult.output}`
      });

      // 품질 검증
      const verificationResult = await context.delegate({
        subagent_type: "oh-my-claudecode:architect",
        model: "opus",
        prompt: `다음 코드가 품질 기준을 충족하는지 검증해주세요:\n${improvementResult.output}\n\n기준: 테스트 커버리지 80% 이상, 복잡도 10 이하, 린트 에러 0개`
      });

      lastResult = verificationResult;
      qualityMet = verificationResult.output.includes("기준 충족");

      if (!qualityMet && currentIteration === maxIterations) {
        return {
          success: false,
          output: `최대 반복 횟수(${maxIterations})에 도달했지만 품질 기준을 충족하지 못했습니다.`
        };
      }
    }

    return {
      success: true,
      output: `${currentIteration}번의 반복 끝에 품질 기준을 충족했습니다.`
    };
  }
};
```

반복 패턴의 핵심은 무한 루프 방지와 종료 조건의 명확성입니다. 최대 반복 횟수와 품질 기준을 명확히 정의해야 합니다.

## 에러 핸들링과 폴백 전략

실제 환경에서는 언제든 에러가 발생할 수 있습니다. 견고한 멀티스텝 워크플로우는 에러를 예상하고 대응 방안을 가지고 있어야 합니다.

```typescript
// 에러 핸들링과 폴백 전략 예시
export const resilientDeploymentSkill: Skill = {
  name: "resilient-deployment",
  description: "에러 발생 시 폴백 전략을 가진 배포 워크플로우",

  async execute(context: SkillContext) {
    try {
      // 주 배포 전략: 자동화된 배포
      const deployResult = await context.delegate({
        subagent_type: "oh-my-claudecode:executor-high",
        model: "opus",
        prompt: "자동화된 배포 스크립트를 실행해주세요."
      });

      if (deployResult.success) {
        return deployResult;
      }

      throw new Error("자동 배포 실패");

    } catch (error) {
      // 폴백 전략 1: 수동 배포 가이드 생성
      try {
        const manualGuide = await context.delegate({
          subagent_type: "oh-my-claudecode:writer",
          model: "haiku",
          prompt: "자동 배포가 실패했습니다. 수동 배포 가이드를 작성해주세요."
        });

        return {
          success: true,
          output: `자동 배포 실패. 수동 배포 가이드:\n${manualGuide.output}`
        };

      } catch (fallbackError) {
        // 폴백 전략 2: 최소한의 롤백
        return {
          success: false,
          output: "배포 및 폴백 전략 모두 실패. 이전 버전으로 롤백을 권장합니다."
        };
      }
    }
  }
};
```

## 풀스택 앱 생성 멀티스텝 스킬 예시

지금까지 배운 모든 패턴을 종합한 실전 예시입니다.

```typescript
export const fullstackAppGeneratorSkill: Skill = {
  name: "fullstack-app-generator",
  description: "풀스택 애플리케이션을 처음부터 끝까지 생성하는 종합 워크플로우",

  async execute(context: SkillContext) {
    const results = [];

    // Step 1: 요구사항 분석
    const requirements = await context.delegate({
      subagent_type: "oh-my-claudecode:analyst",
      model: "opus",
      prompt: `다음 앱에 대한 요구사항을 분석해주세요: ${context.prompt}`
    });
    results.push("✓ 요구사항 분석 완료");

    // Step 2: 아키텍처 설계
    const architecture = await context.delegate({
      subagent_type: "oh-my-claudecode:architect",
      model: "opus",
      prompt: `다음 요구사항에 맞는 풀스택 아키텍처를 설계해주세요:\n${requirements.output}`
    });
    results.push("✓ 아키텍처 설계 완료");

    // Step 3: 백엔드 구현
    const backend = await context.delegate({
      subagent_type: "oh-my-claudecode:executor-high",
      model: "opus",
      prompt: `다음 아키텍처에 따라 백엔드를 구현해주세요:\n${architecture.output}`
    });
    results.push("✓ 백엔드 구현 완료");

    // Step 4: 프론트엔드 구현
    const frontend = await context.delegate({
      subagent_type: "oh-my-claudecode:designer-high",
      model: "opus",
      prompt: `다음 아키텍처에 따라 프론트엔드를 구현해주세요:\n${architecture.output}`
    });
    results.push("✓ 프론트엔드 구현 완료");

    // Step 5: 통합 테스트 (반복 패턴)
    let testsPassed = false;
    for (let i = 0; i < 3 && !testsPassed; i++) {
      const testResult = await context.delegate({
        subagent_type: "oh-my-claudecode:qa-tester-high",
        model: "opus",
        prompt: "풀스택 앱의 통합 테스트를 실행해주세요."
      });

      testsPassed = testResult.success;
      if (!testsPassed && i < 2) {
        // 테스트 실패 시 수정
        await context.delegate({
          subagent_type: "oh-my-claudecode:executor",
          model: "sonnet",
          prompt: `다음 테스트 결과를 바탕으로 버그를 수정해주세요:\n${testResult.output}`
        });
      }
    }
    results.push(testsPassed ? "✓ 통합 테스트 통과" : "⚠ 테스트 일부 실패");

    // Step 6: 문서화
    await context.delegate({
      subagent_type: "oh-my-claudecode:writer",
      model: "haiku",
      prompt: "프로젝트 README와 API 문서를 작성해주세요."
    });
    results.push("✓ 문서화 완료");

    return {
      success: testsPassed,
      output: results.join("\n")
    };
  }
};
```

멀티스텝 워크플로우는 복잡한 작업을 체계적으로 분해하고 관리하는 강력한 도구입니다. 순차 실행, 조건 분기, 반복, 에러 핸들링 패턴을 적절히 조합하면 거의 모든 복잡한 작업을 자동화할 수 있습니다.

# 도구 연동과 스크립트 활용

AI 에이전트의 진정한 힘은 외부 도구와 시스템을 연동하여 실제 작업을 수행할 수 있다는 점입니다. 이번 섹션에서는 REST API 호출, CLI 명령어 실행, MCP 서버 연동, 파일 시스템 조작 등 다양한 도구 연동 방법을 배웁니다.

## 외부 도구 호출: REST API

REST API는 현대 소프트웨어 생태계의 핵심입니다. 스킬에서 외부 서비스를 호출하는 방법을 알아봅시다.

```typescript
import { Skill, SkillContext } from "@claude/skill-sdk";

// GitHub API를 호출하여 이슈를 생성하는 스킬
export const createGitHubIssueSkill: Skill = {
  name: "create-github-issue",
  description: "GitHub 저장소에 이슈를 자동으로 생성합니다",

  async execute(context: SkillContext) {
    const { prompt } = context;

    // 1. 먼저 에이전트에게 이슈 내용을 작성하도록 요청
    const issueContent = await context.delegate({
      subagent_type: "oh-my-claudecode:writer",
      model: "sonnet",
      prompt: `다음 요청사항을 GitHub 이슈 형식으로 작성해주세요:\n${prompt}`
    });

    // 2. Bash 도구를 사용하여 GitHub CLI로 이슈 생성
    const result = await context.tools.bash({
      command: `gh issue create --title "${issueContent.title}" --body "${issueContent.body}"`,
      description: "GitHub CLI를 사용하여 이슈 생성"
    });

    return {
      success: result.exitCode === 0,
      output: `이슈가 성공적으로 생성되었습니다: ${result.stdout}`
    };
  }
};
```

### REST API 직접 호출 패턴

```typescript
// Node.js fetch를 사용한 REST API 호출
export const checkApiHealthSkill: Skill = {
  name: "check-api-health",
  description: "서비스 API의 헬스 체크를 수행합니다",

  async execute(context: SkillContext) {
    const apiUrl = context.config?.apiUrl || "https://api.example.com";

    try {
      // Bash를 통해 curl 실행
      const result = await context.tools.bash({
        command: `curl -s -w "\\n%{http_code}" ${apiUrl}/health`,
        description: "API 헬스 체크 요청",
        timeout: 5000
      });

      const lines = result.stdout.split("\n");
      const statusCode = lines[lines.length - 1];
      const body = lines.slice(0, -1).join("\n");

      const isHealthy = statusCode === "200";

      return {
        success: isHealthy,
        output: isHealthy 
          ? `API가 정상 작동 중입니다. 응답: ${body}`
          : `API가 정상 작동하지 않습니다. 상태 코드: ${statusCode}`
      };

    } catch (error) {
      return {
        success: false,
        output: `API 헬스 체크 실패: ${error.message}`
      };
    }
  }
};
```

## CLI 명령어 실행과 스크립트 활용

Bash나 Python 스크립트를 스킬에서 실행하여 시스템 레벨 작업을 수행할 수 있습니다.

```typescript
// Python 스크립트를 실행하는 스킬
export const runDataAnalysisSkill: Skill = {
  name: "run-data-analysis",
  description: "Python 스크립트를 사용하여 데이터 분석을 수행합니다",

  async execute(context: SkillContext) {
    const { prompt } = context;

    // Step 1: Python 분석 스크립트 생성
    const scriptContent = await context.delegate({
      subagent_type: "oh-my-claudecode:scientist",
      model: "sonnet",
      prompt: `다음 데이터 분석 요청에 대한 Python 스크립트를 작성해주세요:\n${prompt}\n\nPandas와 Matplotlib을 사용하세요.`
    });

    // Step 2: 스크립트를 임시 파일로 저장
    await context.tools.write({
      file_path: "/tmp/analysis.py",
      content: scriptContent.output
    });

    // Step 3: Python 스크립트 실행
    const result = await context.tools.bash({
      command: "python3 /tmp/analysis.py",
      description: "데이터 분석 스크립트 실행",
      timeout: 30000
    });

    // Step 4: 결과 해석
    const interpretation = await context.delegate({
      subagent_type: "oh-my-claudecode:scientist",
      model: "sonnet",
      prompt: `다음 분석 결과를 해석해주세요:\n${result.stdout}`
    });

    return {
      success: result.exitCode === 0,
      output: interpretation.output
    };
  }
};
```

### 복잡한 Bash 스크립트 패턴

```typescript
// 프로젝트 환경 설정을 자동화하는 스킬
export const setupProjectEnvSkill: Skill = {
  name: "setup-project-env",
  description: "프로젝트 개발 환경을 자동으로 설정합니다",

  async execute(context: SkillContext) {
    const setupSteps = [
      {
        name: "의존성 설치",
        command: "npm install",
        critical: true
      },
      {
        name: "환경 변수 파일 생성",
        command: "cp .env.example .env",
        critical: true
      },
      {
        name: "데이터베이스 마이그레이션",
        command: "npm run db:migrate",
        critical: false
      },
      {
        name: "개발 서버 시작",
        command: "npm run dev",
        critical: false,
        background: true
      }
    ];

    const results = [];

    for (const step of setupSteps) {
      try {
        const result = await context.tools.bash({
          command: step.command,
          description: step.name,
          run_in_background: step.background || false
        });

        if (result.exitCode === 0) {
          results.push(`✓ ${step.name} 완료`);
        } else {
          results.push(`✗ ${step.name} 실패: ${result.stderr}`);
          if (step.critical) {
            return {
              success: false,
              output: `필수 단계 실패: ${step.name}\n${results.join("\n")}`
            };
          }
        }
      } catch (error) {
        results.push(`✗ ${step.name} 에러: ${error.message}`);
        if (step.critical) {
          return {
            success: false,
            output: `필수 단계 에러: ${step.name}\n${results.join("\n")}`
          };
        }
      }
    }

    return {
      success: true,
      output: `환경 설정 완료:\n${results.join("\n")}`
    };
  }
};
```

## MCP 서버와의 연동

Model Context Protocol (MCP)은 AI 에이전트가 외부 데이터 소스와 표준화된 방식으로 연동할 수 있게 해주는 프로토콜입니다.

```typescript
// MCP를 통해 데이터베이스와 연동하는 스킬
export const queryDatabaseSkill: Skill = {
  name: "query-database",
  description: "MCP를 통해 데이터베이스를 쿼리합니다",

  async execute(context: SkillContext) {
    const { prompt } = context;

    // Step 1: 자연어 쿼리를 SQL로 변환
    const sqlQuery = await context.delegate({
      subagent_type: "oh-my-claudecode:architect",
      model: "sonnet",
      prompt: `다음 요청을 SQL 쿼리로 변환해주세요:\n${prompt}\n\nPostgreSQL 문법을 사용하세요.`
    });

    // Step 2: MCP 도구를 통해 데이터베이스 쿼리 실행
    // (MCP 서버가 미리 설정되어 있어야 함)
    const result = await context.tools.bash({
      command: `psql -c "${sqlQuery.output}"`,
      description: "데이터베이스 쿼리 실행"
    });

    // Step 3: 결과를 자연어로 해석
    const interpretation = await context.delegate({
      subagent_type: "oh-my-claudecode:writer",
      model: "haiku",
      prompt: `다음 쿼리 결과를 사용자 친화적으로 설명해주세요:\n${result.stdout}`
    });

    return {
      success: result.exitCode === 0,
      output: interpretation.output
    };
  }
};
```

## 파일 시스템 조작

파일 읽기, 쓰기, 생성은 스킬의 기본 기능입니다.

```typescript
// 프로젝트 구조를 분석하고 문서화하는 스킬
export const documentProjectStructureSkill: Skill = {
  name: "document-project-structure",
  description: "프로젝트 구조를 분석하고 문서화합니다",

  async execute(context: SkillContext) {
    // Step 1: 프로젝트 파일 목록 가져오기
    const fileList = await context.tools.bash({
      command: "find . -type f -name '*.ts' -o -name '*.tsx' | head -50",
      description: "TypeScript 파일 목록 조회"
    });

    // Step 2: 주요 파일들의 내용 읽기
    const files = fileList.stdout.split("\n").filter(f => f.trim());
    const fileContents = [];

    for (const file of files.slice(0, 10)) { // 처음 10개만
      try {
        const content = await context.tools.read({
          file_path: file,
          limit: 50 // 처음 50줄만
        });
        fileContents.push({
          path: file,
          summary: content.substring(0, 200)
        });
      } catch (error) {
        // 파일 읽기 실패는 무시
      }
    }

    // Step 3: 구조 분석 및 문서 작성
    const documentation = await context.delegate({
      subagent_type: "oh-my-claudecode:architect",
      model: "opus",
      prompt: `다음 파일 목록과 내용을 바탕으로 프로젝트 구조를 분석하고 README.md에 들어갈 Architecture 섹션을 작성해주세요:\n\n${JSON.stringify(fileContents, null, 2)}`
    });

