```

## 스웜 패턴

스웜 패턴은 여러 에이전트가 동시에 병렬로 작업을 수행하고, 결과를 통합하는 패턴입니다.

```typescript
// 스웜 패턴: 여러 에이전트가 동시에 다른 모듈을 처리
export const parallelModuleUpdateSkill: Skill = {
  name: "parallel-module-update",
  description: "여러 모듈을 동시에 업데이트합니다",

  async execute(context: SkillContext) {
    const modules = [
      { name: "인증 모듈", path: "src/auth", agent: "executor" },
      { name: "API 모듈", path: "src/api", agent: "executor" },
      { name: "UI 컴포넌트", path: "src/components", agent: "designer" },
      { name: "유틸리티", path: "src/utils", agent: "executor-low" }
    ];

    // 모든 모듈을 병렬로 업데이트
    const results = await Promise.all(
      modules.map(async (module) => {
        try {
          const result = await context.delegate({
            subagent_type: `oh-my-claudecode:${module.agent}`,
            model: module.agent.includes("low") ? "haiku" : "sonnet",
            prompt: `${module.name}을 최신 베스트 프랙티스에 맞게 업데이트해주세요. 경로: ${module.path}`
          });

          return {
            module: module.name,
            success: result.success,
            changes: result.output
          };
        } catch (error) {
          return {
            module: module.name,
            success: false,
            error: error.message
          };
        }
      })
    );

    // 결과 통합 및 충돌 감지
    const conflicts = this.detectConflicts(results);

    if (conflicts.length > 0) {
      // 충돌이 있으면 architect에게 해결 요청
      const conflictResolution = await context.delegate({
        subagent_type: "oh-my-claudecode:architect",
        model: "opus",
        prompt: `다음 모듈 간 충돌을 해결해주세요:\n${conflicts.map(c => `- ${c.description}`).join("\n")}`
      });

      return {
        success: true,
        output: `모듈 업데이트 완료 (충돌 해결됨):\n${results.map(r => `✓ ${r.module}`).join("\n")}\n\n충돌 해결:\n${conflictResolution.output}`
      };
    }

    return {
      success: results.every(r => r.success),
      output: `모듈 업데이트 완료:\n${results.map(r => r.success ? `✓ ${r.module}` : `✗ ${r.module}`).join("\n")}`
    };
  },

  detectConflicts(results: any[]) {
    // 간단한 충돌 감지 로직
    const conflicts = [];

    // 예: 같은 파일을 여러 에이전트가 수정했는지 확인
    const modifiedFiles = new Map();

    for (const result of results) {
      // 파일 목록 추출 로직 (실제로는 더 정교해야 함)
      const files = this.extractModifiedFiles(result.changes);

      for (const file of files) {
        if (modifiedFiles.has(file)) {
          conflicts.push({
            description: `${file}이 ${modifiedFiles.get(file)}와 ${result.module}에 의해 동시에 수정됨`
          });
        } else {
          modifiedFiles.set(file, result.module);
        }
      }
    }

    return conflicts;
  },

  extractModifiedFiles(changes: string): string[] {
    // 변경 사항에서 파일 목록 추출 (단순화된 버전)
    return [];
  }
};
```

## 결과 통합과 충돌 해결 전략

여러 에이전트의 결과를 통합할 때는 충돌이 발생할 수 있습니다.

```typescript
// 고급 결과 통합 스킬
export const smartIntegrationSkill: Skill = {
  name: "smart-integration",
  description: "여러 에이전트의 결과를 지능적으로 통합합니다",

  async execute(context: SkillContext) {
    // 다양한 전략 시도
    const strategies = [
      this.tryAutomaticMerge,
      this.tryConflictResolution,
      this.tryManualIntervention
    ];

    for (const strategy of strategies) {
      const result = await strategy.call(this, context);
      if (result.success) {
        return result;
      }
    }

    return {
      success: false,
      output: "모든 통합 전략이 실패했습니다. 수동 개입이 필요합니다."
    };
  },

  async tryAutomaticMerge(context: SkillContext) {
    // 충돌이 없으면 자동 병합
    return { success: false, output: "" };
  },

  async tryConflictResolution(context: SkillContext) {
    // Architect 에이전트에게 충돌 해결 요청
    const resolution = await context.delegate({
      subagent_type: "oh-my-claudecode:architect",
      model: "opus",
      prompt: "충돌을 분석하고 해결 방안을 제시해주세요."
    });
    return resolution;
  },

  async tryManualIntervention(context: SkillContext) {
    // 사용자에게 선택 요청
    return { 
      success: false, 
      output: "자동 해결 불가. 사용자의 결정이 필요합니다." 
    };
  }
};
```

멀티에이전트 협업은 복잡한 프로젝트를 효율적으로 처리하는 핵심 전략입니다. 역할 기반 분담, 파이프라인, 스웜 패턴을 적절히 활용하면 소프트웨어 개발의 거의 모든 측면을 자동화할 수 있습니다.
